 4	
 5	predicate isCelebrity(n : int, i : int)
 6	requires n >= 0 && 0 <= i < n;
 7	{
 8	    forall j :: 0 <= j < n && i != j ==> knows(j, i) && !knows(i, j)
 9	}
10	
11	lemma knowerCannotBeCelebrity(n: int, i: int)
12	requires n >= 0
13	ensures (exists j :: 0 <= j < n && j != i && knows(i, j)) ==> !isCelebrity(n, i)
14	{}
15	
16	ghost method isCelebrityP(n: int, i: int) returns (r : bool)
17	requires n >= 0 && 0 <= i < n;
18	ensures r <==> isCelebrity(n, i);
19	{
20	    var j := 0;
21	    r := true;
22	    while j < n
23	    decreases n - j;
24	    invariant 0 <= j <= n;
25	    invariant r ==> forall k :: 0 <= k < j && k != i ==> knows(k, i) && !knows(i, k);
26	    {
27	        if j != i {
28	            if !knows(j, i) || knows(i, j) {
29	                return false;
30	            }
31	        }
32	        j := j + 1;
33	    }
34	    return r;
35	} 
36	
37	ghost method findCelebrity(n : int) returns (r : int)
38	requires 2 <= n <= 100;
39	ensures 0 <= r < n ==> isCelebrity(n, r);
40	ensures r == -1 ==> forall i :: 0 <= i < n ==> !isCelebrity(n, i);
41	{
42	    var candidate := 0;
43	    var i := 1;
44	    while i < n 
45	    invariant 1 <= i <= n;
46	    invariant forall j :: 0 <= j < i && j != candidate ==> !isCelebrity(n, j);
47	    invariant 0 <= candidate < i;
48	    {
49	        if knows(candidate, i) {
50	            candidate := i;
51	        }
52	        i := i + 1;
53	    }
54	    //assert forall j :: 0 <= j < n && j != candidate ==> !isCelebrity(n, j);
55	    var isCelebrityC := isCelebrityP(n, candidate);
56	    if isCelebrityC {
57	        r := candidate;
58	    } else {
59	        r := -1;
60	    }
61	}

